/* Original scene font, packed as bytes for the existing static asset allowlist. */
(() => {
  if (!window.FontFace || !document.fonts) return;
  const bytes = Uint8Array.from(atob(''), character => character.charCodeAt(0));
  const font = new FontFace('Adelphe', bytes, { display: 'swap' });
  document.fonts.add(font);
  font.load().catch(() => {});
})();
